// Delta application: decode each opcode and apply it to the DOM via the
// retained `id → Node` registry. PARAMETER deltas mutate the hydrated element in
// place; TREE deltas build the element shell and insert/remove/move it; META
// deltas reset/environment.

import {
  CAT_META,
  COLOR_SCHEME_DARK,
  COLOR_SCHEME_LIGHT,
  CAT_PARAMETER,
  CAT_TREE,
  CMD_CREATE_NODE,
  CMD_DELETE_NODE,
  CMD_ENVIRONMENT,
  CMD_INSERT_CHILD,
  CMD_MOVE_CHILD,
  CMD_REMOVE_CHILD,
  CMD_RESET,
  CMD_RESET_THEME,
  CMD_SET_ATTRIBUTED_TEXT,
  CMD_SET_COLOR_SCHEME,
  CMD_SET_DATE,
  CMD_SET_DESIGN_TOKEN,
  CMD_SET_PROPERTY,
  CMD_SET_TEXT,
  CMD_SET_WINDOW_METADATA,
  COMPONENT_COLOR,
  COMPONENT_DIVIDER,
  COMPONENT_GRID,
  COMPONENT_GRID_ROW,
  COMPONENT_HSTACK,
  COMPONENT_LAZY_HGRID,
  COMPONENT_LAZY_HSTACK,
  COMPONENT_LAZY_VGRID,
  COMPONENT_LAZY_VSTACK,
  COMPONENT_PICKER,
  COMPONENT_PROGRESS_VIEW,
  COMPONENT_SCROLLVIEW,
  COMPONENT_SHAPE,
  COMPONENT_SPACER,
  COMPONENT_TEXT,
