  PROP_ENABLED,
  PROP_FONT_DESIGN,
  PROP_FONT_FAMILY,
  PROP_FONT_SIZE,
  PROP_FONT_STYLE,
  PROP_FONT_WEIGHT,
  PROP_GRID_COLUMNS,
  PROP_GRID_ROWS,
  PROP_GRID_TRACKS,
  PROP_IMAGE_SOURCE,
  PROP_IS_INDETERMINATE,
  PROP_LABEL,
  PROP_ICON_NAME,
  PROP_MEDIA_POSITION,
  PROP_MEDIA_VOLUME,
  PROP_NAV_CHROME,
  PROP_NAV_DEPTH,
