            for (Event event : FrameCodec.decodeEvents(message)) {
                if (event.isPointerUp()) {
                    Runnable action = tapActions.get(event.target());
                    if (action != null) action.run();
                } else if (event.isTextChanged()) {
                    name.set(event.text());
                }
            }
        } catch (RuntimeException e) {
            log("dropping event batch: " + e.getMessage());
        }
    }

    String renderHtml() {
        return html.render(rootId).replace("</body>", "<script src=\"/app.js\" defer></script></body>");
    }

    void close() {
        for (EffectRef effect : effects) effect.destroy();
        emitter.destroy();
        connection = null;
    }

