        if (cookie == null) return UUID.randomUUID().toString();
        for (String part : cookie.split(";")) {
            String[] kv = part.trim().split("=", 2);
            if (kv.length == 2 && kv[0].equals("session")) return kv[1];
        }
        return UUID.randomUUID().toString();
    }
}
