  r.byId.set(1, span);

  const text = new TextEncoder().encode("Hi");
  const url = new TextEncoder().encode("javascript:alert(1)");
  const payload = new Uint8Array(4 + text.length + 4 + 4 + 12 + url.length);
  const view = new DataView(payload.buffer);
