package dev.pathland.observability;

import dev.pathland.server.PathlandTelemetry;
import io.micrometer.core.instrument.Counter;
import io.micrometer.core.instrument.DistributionSummary;
import io.micrometer.core.instrument.Gauge;
import io.micrometer.core.instrument.MeterRegistry;
import io.micrometer.core.instrument.Timer;

import java.util.Objects;
import java.util.concurrent.TimeUnit;
import java.util.function.IntSupplier;

/**
 * The Micrometer adapter for {@link PathlandTelemetry}: turns the runtime's
 * lifecycle/throughput events into {@code pathland.*} meters (counters, timers, a
 * distribution summary, and a pull-based active-sessions gauge). Works with any
 * Micrometer registry (Prometheus, OTLP, …) and therefore with both the Quarkus
 * and Spring starters.
 *
 * <p>Every meter is tagged by {@code mount} (a bounded set), so per-app series are
 * available. Registrations are idempotent — Micrometer returns the existing meter
 * for the same name + tags — so calling a builder per event is cheap and cannot
 * leak meters.
 *
 * <h2>Metric catalog</h2>
 * <ul>
 *   <li>{@code pathland.sessions.active} — gauge, live sessions (all mounts)</li>
 *   <li>{@code pathland.sessions.opened} / {@code .closed} — counters</li>
 *   <li>{@code pathland.events.received} — counter, decoded inbound events</li>
 *   <li>{@code pathland.batches.sent} / {@code .frames.sent} / {@code .bytes.sent} — counters</li>
 *   <li>{@code pathland.batch.size} — distribution summary (opcodes per batch)</li>
 *   <li>{@code pathland.batch.flush} — timer (merge + encode)</li>
 *   <li>{@code pathland.ssr.render} — timer (SSR render round-trip)</li>
 *   <li>{@code pathland.resync.requested} — counter</li>
 *   <li>{@code pathland.ws.failures} — counter (a send failed; the client reconnects)</li>
 * </ul>
 */
public final class MicrometerTelemetry implements PathlandTelemetry {

    private static final String PREFIX = "pathland";

    private final MeterRegistry registry;

    public MicrometerTelemetry(MeterRegistry registry) {
        this.registry = Objects.requireNonNull(registry, "registry");
    }

    @Override
    public void bindActiveSessions(IntSupplier supplier) {
        Gauge.builder(PREFIX + ".sessions.active", supplier, IntSupplier::getAsInt)
                .description("Live Pathland sessions across all mounts")
                .register(registry);
    }

    @Override
    public void sessionOpened(String mount) {
        counter("sessions.opened", mount).increment();
    }

    @Override
    public void sessionClosed(String mount) {
        counter("sessions.closed", mount).increment();
    }

    @Override
    public void eventBatchReceived(String mount, int events) {
        counter("events.received", mount).increment(events);
    }

    @Override
    public void batchFlushed(String mount, int frames, int opcodes, int bytes, long nanos) {
        counter("batches.sent", mount).increment();
        counter("frames.sent", mount).increment(frames);
        counter("bytes.sent", mount).increment(bytes);
        DistributionSummary.builder(PREFIX + ".batch.size")
                .baseUnit("opcodes")
                .tag("mount", mount)
                .register(registry)
                .record(opcodes);
        Timer.builder(PREFIX + ".batch.flush")
                .tag("mount", mount)
                .register(registry)
                .record(nanos, TimeUnit.NANOSECONDS);
    }

    @Override
    public void ssrRendered(String mount, long nanos) {
        Timer.builder(PREFIX + ".ssr.render")
                .tag("mount", mount)
                .register(registry)
                .record(nanos, TimeUnit.NANOSECONDS);
    }

    @Override
    public void resyncRequested(String mount) {
        counter("resync.requested", mount).increment();
    }

    @Override
    public void connectionFailed(String mount, String reason) {
        // The reason is deliberately NOT a tag (unbounded cardinality); it is carried
        // for logging adapters. Failures are rare, so a single per-mount counter suffices.
        counter("ws.failures", mount).increment();
    }

    private Counter counter(String name, String mount) {
        return Counter.builder(PREFIX + "." + name)
                .tag("mount", mount)
                .register(registry);
    }
}
    public void open(String uiId, String windowId, PathlandConnection connection) {
        execute(() -> {
            // A WebSocket's first messages can reach the actor before this open task (the
            // transport delivers messages while the endpoint is still wiring the
            // connection). If environment/resync already created the session, attach the
            // connection instead of replacing the session, and re-send the snapshot that
            // may have raced ahead of the connection.
            PathlandSession existing = sessions.get(uiId);
            if (existing != null) {
                existing.connect(connection);
                existing.resync();
                return;
            }
            pending.put(uiId, new PendingSession(stateScope(windowId), connection));
        });
    }

    /** Apply the platform environment: creates the session (seeded from its ROUTE field) on first contact, or enriches it after mount. */
    public void environment(String sessionId, EnvironmentData env) {
        EnvironmentData appEnv = stripRoute(env);
        execute(() -> session(sessionId, appEnv).applyEnvironment(appEnv));
    }

    /** Route an inbound event batch to the owning session (NAVIGATE urls are mount-stripped first). */
    public void dispatch(String sessionId, byte[] message) {
        if (message.length > MAX_EVENT_BATCH) {
            LOG.warn("dropping oversized event batch ({} bytes)", message.length);
            return;
        }
        execute(() -> {
            List<Event> events;
            try {
                events = stripNavigateUrls(FrameCodec.decodeEvents(message));
            } catch (RuntimeException e) {
                LOG.warn("dropping malformed event batch: {}", e.getMessage());
                return;
            }
            telemetry.eventBatchReceived(mountPath, events.size());
            session(sessionId, EnvironmentData.of("/")).dispatch(events);
        });
    }

    /** Handle a META::RESYNC request: re-send the session's current tree as a snapshot. */
    public void resync(String sessionId) {
        execute(() -> {
            telemetry.resyncRequested(mountPath);
            session(sessionId, EnvironmentData.of("/")).resync();
        });
    }

    /** Close and remove a session (and drop any pending connection). */
    public void close(String sessionId) {
        execute(() -> {
            pending.remove(sessionId);
            PathlandSession session = sessions.remove(sessionId);
            if (session != null) {
                session.close();
                telemetry.sessionClosed(mountPath);
            }
        });
    }

    /**
     * Shut down the registry: close every session and stop the actor.
     *
     * <p>Teardown is serialized on the actor, like every other session operation. Closing
     * sessions directly on the caller's thread would race a queued mount/resync that is
     * mutating the same emitter (observed as a {@link java.util.ConcurrentModificationException}
     * during {@code Emitter.destroy}). The call is idempotent and drops any work enqueued
     * after shutdown starts.
     */
    public void shutdown() {
        if (!shuttingDown.compareAndSet(false, true)) {
            return;
        }
        Runnable closeAll = this::closeAllSessions;
        if (Boolean.TRUE.equals(onActor.get())) {
            // Re-entrant shutdown from an actor task: run inline (a submit+get would deadlock).
            closeAll.run();
            actor.shutdown();
            return;
        }
        try {
            actor.submit(() -> runOnActor(closeAll)).get();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } catch (ExecutionException e) {
            LOG.warn("registry shutdown failed: {}", e.getCause() == null ? e.getMessage() : e.getCause().getMessage());
        } catch (RejectedExecutionException ignored) {
            // already shut down
        }
        actor.shutdown();
        try {
            if (!actor.awaitTermination(5, TimeUnit.SECONDS)) {
                actor.shutdownNow();
            }
        } catch (InterruptedException e) {
            actor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    /** Enqueue serialized session work; work is dropped once shutdown has started. */
    private void execute(Runnable task) {
        if (shuttingDown.get()) {
            return;
        }
        try {
            actor.execute(() -> {
                // The shutdown task may have run after this task was queued; don't create
                // sessions/emit work after teardown.
                if (shuttingDown.get()) {
                    return;
                }
                runOnActor(task);
            });
        } catch (RejectedExecutionException ignored) {
            // already shut down
        }
    }

