Fix validateParameter for SET_DESIGN_TOKEN: path at op.a, valueType at op.b low byte, value string at op.c if VAL_STRING. So:
```
case CMD_SET_DESIGN_TOKEN:
  readString(strings, op.a);
  if ((op.b & 0xff) === VAL_STRING) readString(strings, op.c);
  break;
case CMD_SET_TEXT: readString(strings,op.b)
```
Let's edit.

input.oldString:
case CMD_SET_TEXT:
case CMD_SET_DESIGN_TOKEN:
  readString(strings, op.b);
  break;

input.newString:
case CMD_SET_TEXT:
  readString(strings, op.b);
  break;
case CMD_SET_DESIGN_TOKEN: {
  readString(strings, op.a); // token path
  if ((op.b & 0xff) === VAL_STRING) {
    readString(strings, op.c); // string-valued token override
  }
  break;
}

