package dev.pathland.spring;

import dev.pathland.server.PathlandApp;
import dev.pathland.server.test.WsSession;
import org.junit.jupiter.api.Test;
import org.springframework.boot.SpringBootConfiguration;
import org.springframework.boot.autoconfigure.EnableAutoConfiguration;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.context.annotation.Bean;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertThrows;

/**
 * The starter's WebSocket origin policy: same-origin is the default (Spring's
 * handshake check) and a foreign browser origin is rejected. This is the CSRF
 * control for the live-update stream.
 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT,
        classes = WebSocketOriginTest.TestApp.class)
class WebSocketOriginTest {

    @SpringBootConfiguration
    @EnableAutoConfiguration
    static class TestApp {
        @Bean
        PathlandApp pathlandApp() {
            return () -> KotlinFixtures.text("origin");
        }
    }

    @LocalServerPort
    int port;

    private String wsUrl() {
        return "ws://localhost:" + port + "/_pathland/ws";
    }

    @Test
    void sameOriginIsAccepted() {
        String origin = "http://localhost:" + port;
        assertDoesNotThrow(() -> {
            try (WsSession session = WsSession.connect(wsUrl(), "w1", origin)) {
                session.sendEnvironment(800, 600, "/");
            }
        });
    }

    @Test
    void foreignOriginIsRejected() {
        assertThrows(Exception.class, () -> {
            try (WsSession session = WsSession.connect(wsUrl(), "w1", "https://evil.example")) {
                session.sendEnvironment(800, 600, "/");
            }
        });
    }
}

package dev.pathland.quarkus;

import io.quarkus.test.common.http.TestHTTPResource;
import io.quarkus.test.junit.QuarkusTest;
import org.junit.jupiter.api.Test;

import java.net.URI;
import java.net.URL;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** The extension contributes a same-origin CSP and standard security headers. */
@QuarkusTest
class SecurityHeadersTest {

    @TestHTTPResource("/")
    URL base;

    @Test
    void ssrCarriesCspAndSecurityHeaders() throws Exception {
        HttpResponse<String> response = HttpClient.newHttpClient().send(
                HttpRequest.newBuilder(URI.create(base.toString())).GET().build(),
                HttpResponse.BodyHandlers.ofString());
        assertEquals(200, response.statusCode());
        String csp = response.headers().firstValue("Content-Security-Policy").orElse("");
        assertTrue(csp.contains("script-src 'self'"), "scripts are self-only: " + csp);
        assertTrue(csp.contains("style-src 'self' 'unsafe-inline'"),
                "inline protocol styles are allowed: " + csp);
        assertTrue(csp.contains("frame-ancestors 'none'"), "clickjacking is blocked: " + csp);
        assertEquals("nosniff",
                response.headers().firstValue("X-Content-Type-Options").orElse(""));
        assertEquals("no-referrer",
                response.headers().firstValue("Referrer-Policy").orElse(""));
        assertEquals("DENY",
                response.headers().firstValue("X-Frame-Options").orElse(""));
    }
}

package dev.pathland.quarkus;

import dev.pathland.server.test.WsSession;
import io.quarkus.test.common.http.TestHTTPResource;
import io.quarkus.test.junit.QuarkusTest;
import org.junit.jupiter.api.Test;

import java.net.URL;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertThrows;

/**
 * Quarkus's CORS filter runs before the WebSocket route and, with the extension's
 * default ({@code enabled=true}, no explicit origins), enforces same-origin. A foreign
 * browser origin is rejected — the CSRF control for the live-update stream.
 */
@QuarkusTest
class WebSocketOriginTest {

    @TestHTTPResource("/")
    URL base;

    private String wsUrl() {
        return "ws://" + base.getHost() + ":" + base.getPort() + "/_pathland/ws";
    }

    private String sameOrigin() {
        return "http://" + base.getHost() + ":" + base.getPort();
    }

    @Test
    void sameOriginIsAccepted() {
        assertDoesNotThrow(() -> {
            try (WsSession session = WsSession.connect(wsUrl(), "w1", sameOrigin())) {
                session.sendEnvironment(800, 600, "/");
            }
        });
    }

    @Test
    void foreignOriginIsRejected() {
        assertThrows(Exception.class, () -> {
            try (WsSession session = WsSession.connect(wsUrl(), "w1", "https://evil.example")) {
                session.sendEnvironment(800, 600, "/");
            }
        });
    }
}

